CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT UNIQUE NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,tradingview_username TEXT NOT NULL,plan TEXT NOT NULL,payment_method TEXT NOT NULL,transaction_id TEXT NOT NULL,message TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'Pending',created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_orders_order_id ON orders(order_id);